package com.bank.region;

import java.util.Arrays;
import java.util.logging.Logger;

// Captures fully-enclosed open exposures ('O') by flipping them to closed ('X').
public class ExposureContainment {

    private static final Logger log = Logger.getLogger(ExposureContainment.class.getName());

    public char[][] contain(char[][] board) {
        if (board == null || board.length == 0) return board;
        int rows = board.length, cols = board[0].length;

        // Step 1: mark border-connected 'O' as safe 'S'
        for (int r = 0; r < rows; r++) {
            mark(board, r, 0);
            mark(board, r, cols - 1);
        }
        for (int c = 0; c < cols; c++) {
            mark(board, 0, c);
            mark(board, rows - 1, c);
        }

        // Step 2: enclosed 'O' -> 'X'; safe 'S' -> 'O'
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (board[r][c] == 'O') board[r][c] = 'X';
                else if (board[r][c] == 'S') board[r][c] = 'O';
            }
        }
        log.info("Contained board: " + Arrays.deepToString(board));
        return board;
    }

    private void mark(char[][] board, int r, int c) {
        if (r < 0 || c < 0 || r >= board.length || c >= board[0].length) return;
        if (board[r][c] != 'O') return;    // only spread through open cells
        board[r][c] = 'S';                 // safe (border-connected)
        mark(board, r + 1, c);
        mark(board, r - 1, c);
        mark(board, r, c + 1);
        mark(board, r, c - 1);
    }
}
