package com.bank.region;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class RegionDemo {

    private static final Logger log = Logger.getLogger(RegionDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) {
            root.removeHandler(h);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Contain Enclosed Exposures");
        char[][] board = {
            {'X', 'X', 'X', 'X'},
            {'X', 'O', 'O', 'X'},
            {'X', 'X', 'O', 'X'},
            {'X', 'O', 'X', 'X'}
        };
        ExposureContainment service = new ExposureContainment();
        service.contain(board);
        // The middle O-region is enclosed → flipped; bottom-left O touches border → stays
    }
}
